from pathlib import Path
for n in ['llama','mistral','qwen2','phi3','gemma','decilm','glm4','cohere']:
 s=Path('exllamav3/models/'+n+'.py').read_text(); print('\nFILE',n); print(s[:s.find('    def __init__',s.find('class '+ {'llama':'LlamaModel','mistral':'MistralModel','qwen2':'Qwen2Model','phi3':'Phi3Model','gemma':'Gemma2Model','decilm':'DeciLMModel','glm4':'Glm4Model','cohere':'CohereModel'}[n]))])

import ast
from pathlib import Path
p=Path('exllamav3/models')
t=ast.parse((p/'architectures.py').read_text()); d=next(n.value for n in t.body if isinstance(n,ast.Assign) and any(isinstance(x,ast.Name) and x.id=='ARCHITECTURES' for x in n.targets))
old={k.value:{kk.value:(vv.id if isinstance(vv,ast.Name) else vv.value) for kk,vv in zip(v.keys,v.values)} for k,v in zip(d.keys,d.values)}
names=['Llama','Mistral','Qwen2','Phi3','Gemma2','DeciLM','Glm4','Cohere']
new={n+'ForCausalLM':{'architecture':n+'ForCausalLM','config_class':n+'Config','model_class':n+'Model'} for n in names}
print('transcribed new registry equals parent symbolic registry:',new==old,'entries:',len(new))
def check(arch):
 self=type('C',(),{'arch_string':'LlamaForCausalLM','config_filename':'config.json'})()
 assert arch == self.arch_string, f'Unexpected architecture {arch} in {self.config_filename}, should be {expect_arch}.'
for s in ['LlamaForCausalLM','Qwen2ForCausalLM']:
 try: check(s); print(s,'passes')
 except Exception as e: print(s,type(e).__name__,str(e))

